    "tablet_hana": [
      {"days": "both", "from": 0, "to": 24, "at": "nightstand_b1", "chance": "almost_always"}
    ],
    "notebook_hana": [
      {"days": "both", "from": 0, "to": 24, "at": "desk_b1", "chance": "almost_always"},
      {"days": "weekday", "from": 14, "to": 23, "at": "desk_b1", "chance": "almost_always"}
    ],
