      {"days": "weekday", "from": 23, "to": 6, "at": "counter_k1", "chance": "almost_always"}
    ],
    "kitchen_knife_shared": [
      {"days": "both", "from": 0, "to": 24, "at": "counter_k1", "chance": "usually"},
      {"days": "weekday", "from": 23, "to": 6, "at": "counter_k1", "chance": "almost_always"}
    ],
    "class:towel": [
      {"days": "both", "from": 0, "to": 24, "at": "towel_rack_ba1", "chance": "almost_always"}
    ],
    "class:skincare": [
      {"days": "both", "from": 0, "to": 24, "at": "bathroom_shelf_ba1", "chance": "almost_always"}
    ]
